#include "ir_helpers.h"
#include "optimizer_constant_propagation.h"
#include "optimizer_forwarding.h"
#include "optimizer_helpers.h"
#include "optimizer_loop_internal.h"

#include <string.h>

/**
 * @brief State shared by paths from one load to its uses.
 */
typedef struct {
  IrFunction* fn;
  unsigned char* visited;
  IrValueId value;
  IrStackSlotId slot;
} SlotForwarding;

/**
 * @brief Check that no use sees a value overwritten since the original load.
 *
 * @param proof Slot, SSA value, and traversal state.
 * @param id Current block ID.
 * @param start First instruction to inspect in the block.
 * @param overwritten Whether the path has already changed the slot.
 * @return True if all reachable uses still see the captured value.
 */
static bool slot_stable_on_path(const SlotForwarding* proof,
                                IrBlockId id,
                                size_t start,
                                bool overwritten) {
  if (id >= proof->fn->blocks.count)
    return true;

  // A block can be reached with or without an intervening write. Check both.
  if (start == 0) {
    unsigned mask = overwritten ? 2 : 1;

    if (proof->visited[id] & mask)
      return true;

    proof->visited[id] |= mask;
  }

  IrBlock* block = &proof->fn->blocks.data[id];
  for (size_t i = start; i < block->instructions.count; i++) {
    IrInstruction* inst = &block->instructions.data[i];

    // A backedge can reach the load again and start a new snapshot.
    if (inst->result == proof->value)
      return true;

    if (overwritten && optimizer_loop_instruction_uses(inst, proof->value))
      return false;

    if (inst->type == IR_INST_STORE &&
        inst->operands.store.target == proof->slot)
      overwritten = true;
  }

  IrBlockTerminator* term = &block->terminator;
  IrOperand* operand = optimizer_loop_terminator_operand(term);

  if (overwritten && operand &&
      optimizer_loop_direct_use(*operand, proof->value))
    return false;

  if (term->type == IR_TERMINATOR_JUMP)
    return slot_stable_on_path(proof, term->value.jump_target, 0, overwritten);

  if (term->type == IR_TERMINATOR_CONDITIONAL) {
    return slot_stable_on_path(proof,
                               term->value.conditional_target.true_target, 0,
                               overwritten) &&
           slot_stable_on_path(proof,
                               term->value.conditional_target.false_target, 0,
                               overwritten);
  }

  return true;
}

/**
 * @brief Check whether every use of the load still sees its original slot
 * value.
 *
 * @param fn Function containing the load.
 * @param block Block ID containing the load.
 * @param index Instruction index of the load.
 * @param visited Scratch buffer with one byte per block.
 * @return True if the load can be replaced by a direct slot operand.
 */
static bool load_can_forward(IrFunction* fn,
                             IrBlockId block,
                             size_t index,
                             unsigned char* visited) {
  const IrInstruction* load = &fn->blocks.data[block].instructions.data[index];
  memset(visited, 0, fn->blocks.count);
  SlotForwarding proof = {fn, visited, load->result,
                          load->operands.load.source};
  return slot_stable_on_path(&proof, block, index + 1, false);
}

void optimizer_forward_slot_operands(Ctx* ctx, IrFunctionId fid) {
  IrFunction* fn = &ctx->ir.functions.data[fid];

  if (!fn->slots.count)
    return;

  unsigned char* visited = TRY_MALLOC(fn->blocks.count);
  size_t* uses = ctx->optimizer.value_data;
  optimizer_count_value_uses(fn, uses);

  for (IrBlockId b = 0; b < fn->blocks.count; b++) {
    IrInstructionArray* body = &fn->blocks.data[b].instructions;
    for (size_t i = body->count; i-- > 0;) {
      const IrInstruction* load = &body->data[i];

      if (load->type != IR_INST_LOAD || load->result == IR_INVALID_ID ||
          !uses[load->result] || !load_can_forward(fn, b, i, visited))
        continue;

      IrOperand slot = {IR_OP_SLOT, {.slot = load->operands.load.source}};
      optimizer_replace_value(ctx, fid, load->result, slot, false);
      array_remove(ctx, body, i);
    }
  }

  free(visited);
}

/**
 * @brief Insert a load immediately before an instruction or its terminator.
 *
 * @param ctx Compiler context owning the IR.
 * @param fid Function containing the operand.
 * @param bid Block containing the operand.
 * @param[in,out] position Insertion index, advanced past the new load.
 * @param[in,out] operand Operand to rewrite as an SSA reference.
 */
static void materialize_operand(Ctx* ctx,
                                IrFunctionId fid,
                                IrBlockId bid,
                                size_t* position,
                                IrOperand* operand) {
  if (operand->type != IR_OP_SLOT)
    return;

  IrFunction* fn = &ctx->ir.functions.data[fid];
  IrStackSlotId slot = operand->value.slot;
  IrValueId value =
      ir_add_instruction(ctx, fid, bid,
                         (IrInstruction){
                             .type = IR_INST_LOAD,
                             .result_type = fn->slots.data[slot].type,
                             .operands.load.source = slot,
                         });

  // The checked constructor owns the new instruction. Move it before its use.
  IrInstructionArray* body = &fn->blocks.data[bid].instructions;
  size_t end = body->count - 1;
  IrInstruction load = body->data[end];
  memmove(body->data + *position + 1, body->data + *position,
          (end - *position) * sizeof(*body->data));
  body->data[(*position)++] = load;
  *operand = (IrOperand){IR_OP_VALUE, {.id = value}};
}

void optimizer_materialize_slot_operands(Ctx* ctx) {
  for (IrFunctionId fid = 0; fid < ctx->ir.functions.count; fid++) {
    IrFunction* fn = &ctx->ir.functions.data[fid];
    for (IrBlockId b = 0; b < fn->blocks.count; b++) {
      IrBlock* block = &fn->blocks.data[b];
      IrInstructionArray* body = &block->instructions;

      for (size_t i = 0; i < body->count; i++) {
        // The instruction array can grow while the operands are rewritten.
        IrInstruction inst = body->data[i];
        size_t original = i;

        if (inst.type == IR_INST_CALL)
          for (size_t arg = 0; arg < inst.operands.call.arg_count; arg++)
            materialize_operand(ctx, fid, b, &i, &inst.operands.call.args[arg]);
        else {
          IrOperand* operands[3];
          size_t count = optimizer_loop_operands_of(&inst, operands);

          for (size_t op = 0; op < count; op++)
            materialize_operand(ctx, fid, b, &i, operands[op]);
        }

        if (i != original)
          body->data[i] = inst;
      }

      IrOperand* operand =
          optimizer_loop_terminator_operand(&block->terminator);

      if (operand) {
        size_t position = body->count;
        materialize_operand(ctx, fid, b, &position, operand);
      }
    }
  }
}
